-- NIGHTlife: métricas e desativação reversível
-- Execute uma vez no Supabase SQL Editor.
ALTER TABLE public.estabelecimentos ADD COLUMN IF NOT EXISTS ativo boolean NOT NULL DEFAULT true;
CREATE TABLE IF NOT EXISTS public.metricas_estabelecimentos_nightlife(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,estabelecimento_id uuid NOT NULL REFERENCES public.estabelecimentos(id) ON DELETE CASCADE,tipo text NOT NULL CHECK(tipo IN ('visualizacao','whatsapp','rota')),visitante_id text NOT NULL,criado_em timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_metricas_nightlife_estabelecimento ON public.metricas_estabelecimentos_nightlife(estabelecimento_id,tipo);
CREATE UNIQUE INDEX IF NOT EXISTS ux_metricas_nightlife_visualizacao ON public.metricas_estabelecimentos_nightlife(estabelecimento_id,visitante_id) WHERE tipo='visualizacao';
ALTER TABLE public.metricas_estabelecimentos_nightlife ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Proprietarios leem metricas dos seus estabelecimentos" ON public.metricas_estabelecimentos_nightlife;
CREATE POLICY "Proprietarios leem metricas dos seus estabelecimentos" ON public.metricas_estabelecimentos_nightlife FOR SELECT TO authenticated USING (EXISTS(SELECT 1 FROM public.estabelecimentos e WHERE e.id=estabelecimento_id AND e.usuario_id=auth.uid()) OR EXISTS(SELECT 1 FROM public.perfis p WHERE p.id=auth.uid() AND p.tipo='admin'));
CREATE OR REPLACE FUNCTION public.registrar_interacao_nightlife(p_estabelecimento_id uuid,p_tipo text,p_visitante_id text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF p_tipo NOT IN ('visualizacao','whatsapp','rota') OR p_visitante_id IS NULL OR length(p_visitante_id)<8 OR length(p_visitante_id)>120 THEN RAISE EXCEPTION 'Interação inválida.'; END IF;
IF NOT EXISTS(SELECT 1 FROM public.estabelecimentos WHERE id=p_estabelecimento_id AND ativo=true) THEN RETURN; END IF;
IF p_tipo='visualizacao' THEN INSERT INTO public.metricas_estabelecimentos_nightlife(estabelecimento_id,tipo,visitante_id) VALUES(p_estabelecimento_id,p_tipo,p_visitante_id) ON CONFLICT(estabelecimento_id,visitante_id) WHERE tipo='visualizacao' DO NOTHING;
ELSE INSERT INTO public.metricas_estabelecimentos_nightlife(estabelecimento_id,tipo,visitante_id) VALUES(p_estabelecimento_id,p_tipo,p_visitante_id); END IF; END; $$;
GRANT EXECUTE ON FUNCTION public.registrar_interacao_nightlife(uuid,text,text) TO anon,authenticated;
CREATE OR REPLACE FUNCTION public.resumo_metricas_estabelecimento_nightlife(p_estabelecimento_id uuid) RETURNS TABLE(visualizacoes_unicas bigint,cliques_whatsapp bigint,cliques_rota bigint,visitantes_unicos bigint) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF NOT EXISTS(SELECT 1 FROM public.estabelecimentos e WHERE e.id=p_estabelecimento_id AND (e.usuario_id=auth.uid() OR EXISTS(SELECT 1 FROM public.perfis p WHERE p.id=auth.uid() AND p.tipo='admin'))) THEN RAISE EXCEPTION 'Acesso negado às métricas.'; END IF;
RETURN QUERY SELECT count(*) FILTER(WHERE m.tipo='visualizacao'),count(*) FILTER(WHERE m.tipo='whatsapp'),count(*) FILTER(WHERE m.tipo='rota'),count(DISTINCT m.visitante_id) FROM public.metricas_estabelecimentos_nightlife m WHERE m.estabelecimento_id=p_estabelecimento_id; END; $$;
GRANT EXECUTE ON FUNCTION public.resumo_metricas_estabelecimento_nightlife(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.alterar_status_estabelecimento_nightlife(p_estabelecimento_id uuid,p_ativo boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF NOT EXISTS(SELECT 1 FROM public.perfis WHERE id=auth.uid() AND tipo='admin') THEN RAISE EXCEPTION 'Somente administrador pode alterar este status.'; END IF;
UPDATE public.estabelecimentos SET ativo=p_ativo WHERE id=p_estabelecimento_id; IF NOT FOUND THEN RAISE EXCEPTION 'Estabelecimento não encontrado.'; END IF; END; $$;
GRANT EXECUTE ON FUNCTION public.alterar_status_estabelecimento_nightlife(uuid,boolean) TO authenticated;
